const x=$json.body??$json;
const aliases={HOT:'HIGH_TEMPERATURE',TEMPERATURE:'HIGH_TEMPERATURE',HUMIDITY:'HIGH_HUMIDITY',CO2:'HIGH_CO2',CO2_HIGH:'HIGH_CO2',POWER_WASTE:'ENERGY_WASTE',DOOR_AFTER_HOURS:'AFTER_HOURS_DOOR',OFFLINE:'DEVICE_OFFLINE',INVALID_TELEMETRY:'INVALID_PAYLOAD'};
const type=String(x.type||'CUSTOM').trim().toUpperCase().replace(/[\s-]+/g,'_');
const raw=String(x.severity||'WARNING').trim().toUpperCase();
const severity=({LOW:'INFO',MINOR:'INFO',MEDIUM:'WARNING',HIGH:'CRITICAL',SEVERE:'CRITICAL'})[raw]||raw;
if(!['INFO','WARNING','CRITICAL'].includes(severity)) throw new Error('Unsupported incident severity: '+severity);
return {json:{device_id:x.device_id,room:x.room,type:aliases[type]||type,severity,title:String(x.title||type).slice(0,250),observed_at:x.observed_at,details:x.details||{source_workflow:x.source_workflow||'WF05-WF09'}}};
